/**
 * The private `ezg_` grant candidate of one native renewal: generated by the OS, bound to the Gateway grant through its
 * hash only (`tokenSha256`), and stored solely as AES-256-GCM ciphertext under a deployment-pinned wrapping key.
 *
 * - Candidate: `ezg_` + base64url of 32 cryptographically random bytes (43 characters), the Gateway's opaque form.
 * - Hash: lowercase hex SHA-256 of the full UTF-8 token, as the Gateway's `opaqueHash` computes it.
 * - Sealed form: version 1, the wrapping key id, a random 12-byte nonce and ciphertext||tag. The additional data binds
 *   the version, key id, owner, operation, authorization, semantic digest and token hash, so a row, column or key swap
 *   fails authentication. An unknown version or key id fails closed; there is no fallback key.
 *
 * The plaintext leaves this module only inside a `NativeGrantBearer`, whose token is a private field: it is not
 * enumerable, serialises to metadata only and inspects as redacted.
 */

import { createHash } from 'node:crypto';
import { inspect } from 'node:util';

import { base64UrlEncode, nativeCanonicalJson } from './native-authorization-protocol';

export const NATIVE_CANDIDATE_VERSION = 1;
export const NATIVE_CANDIDATE_PURPOSE = 'ezil.native-grant-candidate.v1';
export const NATIVE_CANDIDATE_NONCE_BYTES = 12;
const GCM_TAG_BYTES = 16;
const CANDIDATE = /^ezg_[A-Za-z0-9_-]{43}$/;
const SHA256_HEX = /^[0-9a-f]{64}$/;

export interface NativeWrappingKey {
    readonly keyId: string;
    /** Non-extractable AES-256-GCM key, encrypt and decrypt only. */
    readonly key: CryptoKey;
}

/** Everything the sealed candidate is bound to. */
export interface NativeCandidateBinding {
    readonly ownerUserId: string;
    readonly operationId: string;
    readonly authorizationId: string;
    readonly semanticDigest: string;
    readonly tokenSha256: string;
}

export interface SealedNativeCandidate {
    readonly version: number;
    readonly keyId: string;
    readonly nonce: Uint8Array;
    readonly ciphertext: Uint8Array;
}

/** Length of a sealed candidate: the 47-byte ASCII token plus the GCM tag. */
export const NATIVE_CANDIDATE_CIPHERTEXT_BYTES = 47 + GCM_TAG_BYTES;

export function isNativeGrantCandidate(value: unknown): value is string {
    return typeof value === 'string' && CANDIDATE.test(value);
}

/** A fresh candidate from 32 CSPRNG bytes. */
export function newNativeGrantCandidate(): string {
    return `ezg_${base64UrlEncode(crypto.getRandomValues(new Uint8Array(32)))}`;
}

/** Lowercase hex SHA-256 of the full UTF-8 token. */
export function nativeTokenSha256(token: string): string {
    return createHash('sha256').update(token, 'utf8').digest('hex');
}

function additionalData(version: number, keyId: string, binding: NativeCandidateBinding): Uint8Array {
    return new TextEncoder().encode(nativeCanonicalJson({
        purpose: NATIVE_CANDIDATE_PURPOSE, version, keyId,
        ownerUserId: binding.ownerUserId, operationId: binding.operationId, authorizationId: binding.authorizationId,
        semanticDigest: binding.semanticDigest, tokenSha256: binding.tokenSha256,
    }));
}

export class NativeCandidateError extends Error {
    constructor(readonly reason: 'candidate_invalid' | 'binding_invalid') {
        super(`native_${reason}`);
        this.name = 'NativeCandidateError';
    }
}

/** Seals `candidate` for `binding`. Refuses a candidate whose hash is not the bound `tokenSha256`. */
export async function sealNativeCandidate(wrapping: NativeWrappingKey, candidate: string,
    binding: NativeCandidateBinding): Promise<SealedNativeCandidate> {
    if (!isNativeGrantCandidate(candidate)) throw new NativeCandidateError('candidate_invalid');
    if (!SHA256_HEX.test(binding.tokenSha256) || nativeTokenSha256(candidate) !== binding.tokenSha256) {
        throw new NativeCandidateError('binding_invalid');
    }
    const nonce = crypto.getRandomValues(new Uint8Array(NATIVE_CANDIDATE_NONCE_BYTES));
    const ciphertext = new Uint8Array(await crypto.subtle.encrypt(
        { name: 'AES-GCM', iv: nonce, additionalData: additionalData(NATIVE_CANDIDATE_VERSION, wrapping.keyId, binding) as Uint8Array<ArrayBuffer>, tagLength: 128 },
        wrapping.key, new TextEncoder().encode(candidate)));
    return Object.freeze({ version: NATIVE_CANDIDATE_VERSION, keyId: wrapping.keyId, nonce, ciphertext });
}

/**
 * The plaintext candidate, or null when the version or key id is not the pinned one, the nonce or ciphertext has the
 * wrong length, authentication fails (tampered ciphertext, nonce or any bound field), or the plaintext is not an
 * `ezg_` token whose hash is the bound `tokenSha256`.
 */
export async function openNativeCandidate(wrapping: NativeWrappingKey, sealed: SealedNativeCandidate,
    binding: NativeCandidateBinding): Promise<string | null> {
    if (sealed.version !== NATIVE_CANDIDATE_VERSION || sealed.keyId !== wrapping.keyId) return null;
    if (sealed.nonce.byteLength !== NATIVE_CANDIDATE_NONCE_BYTES || sealed.ciphertext.byteLength !== NATIVE_CANDIDATE_CIPHERTEXT_BYTES) return null;
    let plain: ArrayBuffer;
    try {
        plain = await crypto.subtle.decrypt(
            { name: 'AES-GCM', iv: sealed.nonce as Uint8Array<ArrayBuffer>, additionalData: additionalData(sealed.version, sealed.keyId, binding) as Uint8Array<ArrayBuffer>, tagLength: 128 },
            wrapping.key, sealed.ciphertext as Uint8Array<ArrayBuffer>);
    } catch {
        return null;
    }
    let token: string;
    try { token = new TextDecoder('utf-8', { fatal: true }).decode(plain); } catch { return null; }
    return isNativeGrantCandidate(token) && nativeTokenSha256(token) === binding.tokenSha256 ? token : null;
}

/**
 * A granted candidate opened for the closed private host transport. The token is reachable only through
 * `authorizationHeader()`; JSON, string conversion and inspection show metadata only.
 */
export class NativeGrantBearer {
    readonly #token: string;
    readonly operationId: string;
    readonly grantId: string;
    readonly expiresAt: Date;

    constructor(token: string, operationId: string, grantId: string, expiresAt: Date) {
        if (!isNativeGrantCandidate(token)) throw new NativeCandidateError('candidate_invalid');
        this.#token = token;
        this.operationId = operationId;
        this.grantId = grantId;
        this.expiresAt = new Date(expiresAt.getTime());
        Object.freeze(this);
    }

    /** The bearer header value, for the private host transport only. */
    authorizationHeader(): string {
        return `Bearer ${this.#token}`;
    }

    toJSON(): { operationId: string; grantId: string; expiresAt: string } {
        return { operationId: this.operationId, grantId: this.grantId, expiresAt: this.expiresAt.toISOString() };
    }

    toString(): string {
        return '[NativeGrantBearer redacted]';
    }

    [inspect.custom](): string {
        return this.toString();
    }
}
